ALTER TABLE IF EXISTS treatment_procedures_master ADD CONSTRAINT IF NOT EXISTS uq_treatment_proc_category_name UNIQUE (category_id, name);
INSERT INTO treatment_categories_master (category_key, title, display_order, is_active, created_at, updated_at) VALUES ('conservative', 'Conservative Dentistry & Restoration', 1, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (category_key) DO UPDATE SET title=EXCLUDED.title, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='conservative' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Composite fillings', 'I consent to the Composite Filling procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'Please avoid disturbing the area after your Composite fillings; gentle care helps proper healing. A slight discomfort is normal after restoring tooth structure; take prescribed medication if needed. Avoid hard, hot, or sticky foods that may interfere with healing after Composite fillings. Maintain gentle oral hygiene and avoid direct pressure on the treated tooth or area. Contact us immediately if swelling, severe pain, or unusual symptoms appear after Composite fillings.', true, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
