WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='periodontology' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Flap surgery', 'I consent to the Flap Surgery procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'Following flap surgery, expect some discomfort and swelling. Use prescribed pain relievers as necessary, and avoid chewing on the surgical area for a few days. Keep the area clean with gentle brushing, but avoid direct pressure on the treated gums. It''s normal to have mild bleeding during the first few days. Regular follow-ups are necessary for optimal healing. If you notice excessive pain, persistent bleeding, or other complications, contact us immediately.', true, 4, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='periodontology' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Gingivectomy', 'I consent to the Gingivectomy procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'After gingivectomy, avoid eating hard or spicy foods for the first few days. Mild discomfort and swelling are expected; take pain relief as prescribed. Keep the surgical site clean with gentle brushing, but avoid direct contact with the gums. Avoid smoking and alcohol as they may delay healing. Follow-up visits are important to assess healing. Contact us if you experience excessive pain, swelling, or any unusual symptoms.', true, 5, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='periodontology' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Gingivoplasty', 'I consent to the Gingivoplasty procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'After gingivoplasty, you may experience mild swelling and discomfort. Use pain relievers as needed, and avoid eating foods that may irritate the treated area. Gentle brushing and flossing around the gums are encouraged. Avoid aggressive cleaning of the treated area to allow proper healing. Regular follow-ups are essential to ensure the treatment’s success. Contact us if you experience any complications such as infection or excessive bleeding.', true, 6, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='periodontology' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Crown lengthening', 'I consent to the Crown Lengthening procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'Post-surgery, avoid chewing on the treated area for a few days to allow proper healing. Mild discomfort and swelling are common, and pain relievers can be taken as needed. Keep the treated area clean with gentle brushing, and avoid pressure on the gums. Avoid hard or sticky foods that may irritate the area. If swelling, pain, or bleeding persist, contact us immediately for further evaluation.', true, 7, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='periodontology' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Frenectomy', 'I consent to the Frenectomy procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'After frenectomy, expect mild swelling and discomfort. Avoid chewing on the treated area until fully healed. Follow prescribed care instructions and keep the area clean with gentle brushing. Avoid activities that may put pressure on the treated area. Regular check-ups are essential to monitor the healing process. Contact us if you notice unusual pain or swelling that doesn’t subside.', true, 8, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
