WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='prosthodontics' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Conventional Bridge', 'I consent to the Conventional Bridge procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'After receiving your conventional bridge, be mindful to avoid chewing on hard objects for a few days. Mild sensitivity may occur, but this should improve with time. Keep up with good oral hygiene around the bridge, and avoid putting too much pressure on it. Visit us regularly to ensure the bridge stays in place and functions properly. Contact us if you notice any looseness, discomfort, or issues with the bridge.', true, 24, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
