WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='oms' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Impacted Tooth Removal', 'I consent to the Impacted Tooth Removal procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'Impacted tooth removal is more complex, and post-surgical care is crucial. Expect some swelling and discomfort post-operation. Follow instructions for rest, medication, and limiting physical activity for the first few days to support healing.', true, 23, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='oms' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Orthognathic Surgery', 'I consent to the Orthognathic Surgery procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'Orthognathic surgery requires an extended recovery period. You may experience significant swelling, discomfort, and bruising. Follow your post-operative care instructions closely, take medications as prescribed, and attend all follow-up visits to ensure proper healing.', true, 32, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
