WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='implantology' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Zygomatic implants', 'I consent to the Zygomatic Implant procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'Zygomatic implants are often used for patients with insufficient bone in the upper jaw. You may experience more swelling and discomfort than with traditional implants. Follow care instructions closely, including avoiding chewing hard foods and keeping the area clean.', true, 4, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='implantology' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Pterygoid implants', 'I consent to the Pterygoid Implant procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'Pterygoid implants are placed in the upper jaw and are a solution for patients with significant bone loss. Swelling and discomfort are common. Strict post-operative care and regular check-ups are essential for optimal healing and implant integration.', true, 5, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='implantology' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Mini implants', 'I consent to the Mini Implant procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'Mini implants offer a less invasive alternative with a quicker recovery time. Expect some discomfort and swelling, which should subside after a few days. Follow oral hygiene recommendations and attend follow-up visits to ensure the implants are successful.', true, 6, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='implantology' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Immediate implants', 'I consent to the Immediate Implant procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'Immediate implants are placed at the time of tooth extraction. Post-operative care is crucial. Avoid hard foods for a few weeks and follow your dentist’s recommendations for pain management and healing support.', true, 7, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='implantology' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Immediate loading implants', 'I consent to the Immediate Loading Implant procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'Immediate loading implants allow for a quicker recovery and function. Post-operative care includes following medication schedules and maintaining proper oral hygiene. Avoid chewing on the implant site during the initial healing phase.', true, 8, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='implantology' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Bone grafting', 'I consent to the Bone Grafting procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'Bone grafting is essential for creating a stable foundation for implants. Expect swelling, discomfort, and a period of limited mobility. Careful adherence to post-operative instructions is essential to ensure successful grafting and healing.', true, 9, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='implantology' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Sinus lift', 'I consent to the Sinus Lift procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'A sinus lift is performed to enhance bone growth for implant placement. Swelling and discomfort are common post-surgery. Follow all aftercare instructions, including avoiding blowing your nose and taking pain medications as prescribed.', true, 10, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='implantology' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Ridge expansion', 'I consent to the Ridge Expansion procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'Ridge expansion may be necessary if there is insufficient bone for implant placement. Expect swelling and discomfort in the initial days. Follow prescribed post-operative care and attend follow-up appointments for assessment.', true, 11, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='implantology' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Socket preservation', 'I consent to the Socket Preservation procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'Socket preservation is performed to preserve bone after tooth extraction. You may experience mild swelling and discomfort post-surgery. Follow your dentist’s instructions for oral hygiene and healing, and avoid any direct pressure on the socket.', true, 12, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
