WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='implantology' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Peri-implantitis treatment', 'I consent to the Peri-implantitis Treatment procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'Peri-implantitis treatment aims to address infection around implants. Expect some discomfort and follow strict aftercare instructions, including regular cleaning and medication. Additional treatments may be needed to ensure the implant remains healthy.', true, 14, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='implantology' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Single Dental Implant', 'I consent to the Single Dental Implant procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'After the placement of a single dental implant, avoid chewing on the implant site for a few days. Swelling and mild discomfort are common. Follow your dentist’s instructions for post-operative care, including medication and hygiene practices to promote healing.', true, 15, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='implantology' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Multiple Dental Implants', 'I consent to the Multiple Dental Implants procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'Multiple dental implants may require a longer recovery time. You may experience swelling, discomfort, and possible bruising. Follow a soft diet and take prescribed medications as directed. Follow-up appointments are important to check for implant stability and healing.', true, 16, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='implantology' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'All-on-4 Implants', 'I consent to the All-on-4 Implants procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'All-on-4 implants provide a full set of teeth on just four implants. Swelling and discomfort are normal post-surgery. Follow your dentist’s care plan, avoid chewing on the implants for a few days, and attend follow-up visits to ensure the implants are stable.', true, 17, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='implantology' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'All-on-6 Implants', 'I consent to the All-on-6 Implants procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'After All-on-6 implants, it''s important to follow the prescribed oral hygiene regimen and take pain medications as needed. Avoid strenuous activities for a few weeks to support the healing process. Regular follow-up appointments will ensure proper integration of the implants.', true, 18, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
INSERT INTO treatment_categories_master (category_key, title, display_order, is_active, created_at, updated_at) VALUES ('pediatric', 'Pediatric Dentistry (Children’s Dentistry)', 8, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (category_key) DO UPDATE SET title=EXCLUDED.title, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='pediatric' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Fluoride application', 'I consent to the Fluoride Application procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'Fluoride treatment helps prevent cavities and strengthen enamel. The child may experience mild discomfort, but the procedure is non-invasive. After the application, avoid eating or drinking for at least 30 minutes to allow the fluoride to work effectively.', true, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='pediatric' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Sealants', NULL, NULL, true, 2, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='pediatric' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Pulpotomy', 'I consent to the Pulpotomy procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'A pulpotomy involves removing the infected pulp tissue in the tooth to preserve it. After the procedure, the child may experience mild discomfort. Follow up with prescribed pain management and avoid hard foods for a few days.', true, 3, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='pediatric' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Pulpectomy', 'I consent to the Pulpectomy procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'A pulpectomy is a deeper procedure where the entire pulp tissue is removed from the tooth. The child may experience swelling and discomfort, which can be managed with prescribed medication. Avoid chewing on the treated tooth until fully healed.', true, 4, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='pediatric' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Stainless steel crowns', 'I consent to the Stainless Steel Crown procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'A stainless steel crown is used to restore and protect decayed or damaged teeth. It may feel different initially, but this discomfort usually subsides. Keep the child’s mouth clean and avoid sticky or hard foods to prevent damaging the crown.', true, 5, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='pediatric' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Strip crowns', 'I consent to the Strip Crown procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'Strip crowns are used to restore decayed front teeth. They are aesthetically pleasing and blend well with natural teeth. Maintain proper oral hygiene and avoid biting into hard objects to protect the crown.', true, 6, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='pediatric' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Space maintainers', 'I consent to the Space Maintainer procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'Space maintainers are used to preserve space for permanent teeth when a primary tooth is lost prematurely. Ensure the child avoids chewing on the maintainer, as it can affect its placement. Regular check-ups are necessary to monitor the appliance.', true, 7, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
