WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='emergency' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Trauma stabilization', 'I consent to the Trauma Stabilization procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'Trauma stabilization helps to secure a displaced tooth or restore stability following an injury. Follow-up appointments are necessary for healing and restoration.', true, 9, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='emergency' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Pain Management', 'I consent to the Pain Management procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'Pain management may include medications or techniques to alleviate discomfort following a dental emergency. Be sure to follow your dentist''s aftercare instructions.', true, 10, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='emergency' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'Abscess Drainage', 'I consent to the Abscess Drainage procedure as recommended by my dentist for my specific dental condition. I understand the purpose of this treatment, the expected benefits, and the possible risks such as post-operative discomfort, sensitivity, healing variations, or the need for additional procedures. I acknowledge that outcomes may depend on the condition of the tooth, my oral hygiene, and compliance with after-care instructions. I am aware that follow-up visits, adjustments, or supplementary treatment may be required to achieve optimal results. I authorize my dentist to modify or extend the treatment plan if unexpected findings occur during the procedure, acting in my best clinical interest.', 'Abscess drainage is used to remove pus and relieve pressure caused by infection. You may need antibiotics and follow-up visits to ensure complete healing.', true, 11, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
INSERT INTO treatment_categories_master (category_key, title, display_order, is_active, created_at, updated_at) VALUES ('others', 'Others', 12, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (category_key) DO UPDATE SET title=EXCLUDED.title, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;
WITH cat AS (SELECT id FROM treatment_categories_master WHERE category_key='others' LIMIT 1) INSERT INTO treatment_procedures_master (category_id, name, consent_text, guideline_text, is_active, display_order, created_at, updated_at) SELECT cat.id, 'General Dental Treatment', 'I hereby provide my full and informed consent for all general dental treatments including examinations, diagnostic procedures, X‑rays, cleaning, fillings, preventive care, and any other routine procedures deemed necessary by my dentist. I understand that dentistry is not an exact science and that treatment outcomes can vary depending on individual healing patterns, oral hygiene practices, and the condition of my teeth and gums. I acknowledge that certain procedures may involve temporary discomfort, sensitivity, gum irritation, or the need for follow-up visits. I authorize my dentist to perform additional procedures if unexpected conditions are discovered during treatment, provided they are in my best interest. I also understand my responsibility to follow all post‑treatment instructions, attend recommended follow-up appointments, and disclose accurate medical history to support safe and effective care. By signing, I confirm that all my questions have been answered to my satisfaction and that I fully understand the nature, purpose, potential risks, benefits, and alternatives of routine dental care.', 'Follow the prescribed medicines exactly to ensure smooth healing. Maintain gentle oral hygiene, avoiding aggressive brushing. For the first 24 hours, avoid extreme hot, cold, or hard foods. Use warm salt-water rinses twice daily to reduce inflammation and attend scheduled follow-up visits for optimal recovery. If you experience severe pain, swelling, bleeding, or fever, report it immediately.', true, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM cat ON CONFLICT (category_id, name) DO UPDATE SET consent_text=EXCLUDED.consent_text, guideline_text=EXCLUDED.guideline_text, display_order=EXCLUDED.display_order, is_active=TRUE, updated_at=EXCLUDED.updated_at;